// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 actorSeed) public {
        address actor = address(uint160(uint256(keccak256(abi.encode(actorSeed)))));
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        uint256 amount = 10 ether;
        vm.deal(actor, amount * 2);

        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: amount}("");
        assertTrue(ok1);

        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: amount}("");

        assertTrue(ok2 == false);
    }
}
